type Row=Record<string,string|number|null>;
const now=()=>new Date().toISOString(),hash=(v:string|Buffer)=>createHash('sha256').update(v).digest('hex');
const configDigest=()=>hash([process.env.RAZORPAY_CLIENT_ID,process.env.RAZORPAY_CLIENT_SECRET,process.env.RAZORPAY_MODE,process.env.UPI_TOKEN_ENCRYPTION_KEY].join(':'));
